  'my.title': 'സെറ്റിംഗ്സും സേവ് ചെയ്ത ഡാറ്റയും', 'my.intro': 'Nivesh Sahayak-ന്റെ എല്ലാ ഡോക്യുമെന്റ് ടൂളുകളും ഒരിടത്ത് നിന്ന് സെറ്റ് ചെയ്യാം: നിങ്ങളുടെ ബിസിനസുകൾ, കസ്റ്റമർമാരും സപ്ലയർമാരും, ഐറ്റങ്ങളും സർവീസുകളും, നമ്പറിംഗും ഡിഫോൾട്ടുകളും. എല്ലാം ഈ ബ്രൗസറിൽ തന്നെ ഇരിക്കും. ഞങ്ങൾക്ക് ഒന്നും അയയ്ക്കില്ല.',
