  "ei.h.aato": "ഇ-ഇൻവോയ്സ് നിങ്ങൾക്ക് ബാധകമാണോ, 30 ദിവസത്തെ പരിധി ബാധകമാണോ എന്ന് ഇതിലൂടെ തീരുമാനിക്കും. ഇത് ഈ ബ്രൗസറിൽ തന്നെ ഓർമ്മയിലിരിക്കും.",
  "ev.hsn6": "ഐറ്റം {n}: ഇ-ഇൻവോയ്സിൽ 6 അല്ലെങ്കിൽ 8 അക്ക HSN/SAC കോഡ് വേണം (4 അക്കം ₹5 കോടിയിൽ താഴെയുള്ള, ഇ-ഇൻവോയ്സ് ചെയ്യാത്ത ബിസിനസുകൾക്ക് മാത്രം).",
  "ev.old30": "ഈ ഇൻവോയ്സ് 30 ദിവസമോ അതിൽ കൂടുതലോ പഴയതാണ്. ₹10 കോടിയോ കൂടുതലോ ടേണോവർ ഉണ്ടെങ്കിൽ പോർട്ടൽ ഇത് ഇനി രജിസ്റ്റർ ചെയ്യില്ല. പുതിയ ഇൻവോയ്സ് ഉണ്ടാക്കുന്നതിന് മുമ്പ് നിങ്ങളുടെ അക്കൗണ്ടന്റിനോട് ചോദിക്കുക.",
  "ev.lt5": "2017-18 മുതൽ ഏതെങ്കിലും വർഷം നിങ്ങളുടെ ടേണോവർ ₹5 കോടി കടന്നിട്ടില്ലെങ്കിൽ ഇ-ഇൻവോയ്സ് നിങ്ങൾക്ക് നിർബന്ധമല്ല.",
  "ev.old180": "180 ദിവസത്തിൽ കൂടുതൽ പഴയ ഡോക്യുമെന്റിന് പോർട്ടൽ ഇ-വേ ബിൽ ഉണ്ടാക്കില്ല.",
  "ev.smallst": "{st} ഉള്ളിൽ ഇ-വേ ബിൽ സാധാരണയായി ₹{v}-ൽ കൂടിയാൽ മാത്രമേ വേണ്ടൂ (മറ്റൊരു സംസ്ഥാനത്തേക്ക് ₹50,000-ൽ കൂടുതൽ; മറ്റൊരു സംസ്ഥാനത്തേക്ക് പോകുന്ന ജോബ് വർക്കിനും കരകൗശല വസ്തുക്കൾക്കും ഏത് തുകയ്ക്കും വേണം).",
  "ev.fromirn": "നിങ്ങളുടെ ബിസിനസ് ഇ-ഇൻവോയ്സ് ചെയ്യേണ്ടതാണെങ്കിൽ, ഈ ഇൻവോയ്സിന്റെ ഇ-വേ ബിൽ പോർട്ടൽ അതിന്റെ IRN-ൽ നിന്ന് മാത്രമേ ഉണ്ടാക്കൂ: “ഇ-ഇൻവോയ്സിനൊപ്പം ഇ-വേ ബില്ലും ഉണ്ടാക്കുക” ടിക്ക് ചെയ്ത് ഇ-ഇൻവോയ്സ് ഫയൽ ഉണ്ടാക്കുക.",
  "ev.tidchk": "ട്രാൻസ്പോർട്ടർ ID-യുടെ അവസാന അക്ഷരം യോജിക്കുന്നില്ല. ടൈപ്പിംഗ് പിശകാണോ എന്ന് ഒന്ന് പരിശോധിക്കുക.",
  "ei.rmnote": "നിങ്ങൾ ഈ IRN പോർട്ടലിൽ ക്യാൻസൽ ചെയ്തിട്ടുണ്ടെങ്കിൽ, ഈ ഇൻവോയ്സ് നമ്പർ ഇനി ഒരിക്കലും രജിസ്റ്റർ ആകില്ല. ശരിയായ ഇൻവോയ്സ് പുതിയ നമ്പറിൽ ഉണ്ടാക്കുക.",
  /* tax rule fixes, bills (4 Nov 2026) */
  "hub.reg": "GST രജിസ്ട്രേഷൻ",
