  "v.b2c": "GSTIN ഇല്ലാത്ത കസ്റ്റമർക്ക് ₹50,000 അല്ലെങ്കിൽ അതിൽ കൂടുതൽ ബില്ലിന് GST നിയമപ്രകാരം കസ്റ്റമറുടെ പേര്, വിലാസം, സംസ്ഥാനം വേണം.",
