  "v.orig": "ഈ നോട്ട് ഏത് ഇൻവോയ്സിനുള്ളതാണോ അതിന്റെ നമ്പറും തീയതിയും ടൈപ്പ് ചെയ്യുക. GST നിയമപ്രകാരം നോട്ടിൽ അവ വേണം.",
  "v.naddr": "GSTIN ഇല്ലാത്ത വാങ്ങുന്നയാൾക്ക്, അവരുടെ വിലാസവും സംസ്ഥാനവും ടൈപ്പ് ചെയ്യുക.",
  "c.cn30": "ഈ ക്രെഡിറ്റ് നോട്ടിന്റെ തീയതി, ആ ഇൻവോയ്സിന്റെ സാമ്പത്തിക വർഷം കഴിഞ്ഞുള്ള 30 നവംബറിന് ശേഷമാണ് (അല്ലെങ്കിൽ ആ വർഷത്തെ വാർഷിക റിട്ടേൺ അതിന് മുമ്പേ ഫയൽ ചെയ്തിട്ടുണ്ടെങ്കിൽ, അതിന് ശേഷം). ആ തീയതിക്ക് ശേഷം അതിലെ GST കുറയ്ക്കാൻ കഴിയില്ല (ബിസിനസ് ഡോക്യുമെന്റ് എന്ന നിലയിൽ നോട്ട് സാധുവാണ്). എന്നാലും സേവ് ചെയ്യണോ?",
  "s.tds": "പണം തന്നയാൾ പിടിച്ച TDS (₹)",
