  "c.si30": "ഈ സെൽഫ് ഇൻവോയ്സിന്റെ തീയതി, സാധനമോ സർവീസോ കിട്ടി 30 ദിവസത്തിന് ശേഷമാണ്. നിയമപ്രകാരം 30 ദിവസത്തിനുള്ളിൽ വേണം. എന്നാലും സേവ് ചെയ്യണോ?",
