  "app.helpp": "billing., cash-memo., credit-note. എന്നിവയിൽ ഉണ്ടാക്കിയ ബില്ലുകൾ ഇവിടെ തനിയെ കാണാം. കിട്ടിയതും കൊടുത്തതുമായ പണം ഇവിടെ എഴുതൂ; ആപ്പ് അത് ബില്ലുകളുമായി ബന്ധിപ്പിക്കുന്നു, അഡ്വാൻസ് സൂക്ഷിക്കുന്നു, കുടിശ്ശികയും കൈയിലുള്ള ക്യാഷും കണക്കാക്കുന്നു.",
  "app.invfix": "ഇവിടെ തീർത്ത ഇൻവോയ്സുകൾ ബില്ലിംഗ് സൈറ്റിലും അടച്ചു എന്ന് കാണിക്കും.",
  "app.ex_rent": "വാടക",
  "app.ex_power": "കറന്റ്",
  "app.ex_salary": "ശമ്പളവും കൂലിയും",
  "app.ex_transport": "ട്രാൻസ്പോർട്ടും ലോറി വാടകയും",
  "app.ex_phone": "ഫോണും ഇന്റർനെറ്റും",
  "app.ex_repair": "റിപ്പയറും മെയിന്റനൻസും",
  "app.ex_office": "ഓഫീസ് ചെലവുകൾ",
  "app.ex_fuel": "പെട്രോൾ-ഡീസൽ",
  "app.ex_bank": "ബാങ്ക് ചാർജുകൾ",
  "app.ex_prof": "പ്രൊഫഷണൽ ഫീസ്",
  "app.ex_ads": "പരസ്യം",
  "app.ex_misc": "മറ്റ് ചെലവുകൾ",
  "app.back": "‹ പിന്നോട്ട്",
  "app.advance": "അഡ്വാൻസ്",
  "app.advh": "ബില്ലിന് മുൻപ് കിട്ടിയതോ കൊടുത്തതോ ആയ പണം.",
  "app.intro": "നിങ്ങളുടെ ബില്ലുകൾ, കിട്ടിയതും കൊടുത്തതുമായ പണം, വാങ്ങലുകൾ, ചെലവുകൾ, കുടിശ്ശിക എല്ലാം ഒരിടത്ത്. ഇത് സൗജന്യ ഡോക്യുമെന്റ് മേക്കറുകളുടെ (ബില്ലിംഗ്, ക്വട്ടേഷൻ, രസീത് മുതലായവ) അതേ സേവ് ചെയ്ത ഡാറ്റ ഉപയോഗിക്കുന്നു, അതിനാൽ അവിടെ ഉണ്ടാക്കിയ എല്ലാ ബില്ലും ഇവിടെ കാണാം. സൗജന്യം, ലോഗിൻ വേണ്ട, ഡാറ്റ ഈ ബ്രൗസറിൽ തന്നെ.",
  "app.ab.h": "ചെറിയ ബിസിനസിന് ആപ്പ് എന്തു ചെയ്യുന്നു",
  "app.ab.p": "മിക്ക സൗജന്യ ബിൽ മേക്കറുകളും ബിൽ ഉണ്ടാക്കി നിർത്തുന്നു. Nivesh Sahayak App മുന്നോട്ട് പോകുന്നു: ഓരോ പേയ്മെന്റും അത് തീർക്കുന്ന ബില്ലുകളുമായി ബന്ധിപ്പിക്കുന്നു, അതിനാൽ ഏത് കസ്റ്റമർ എത്ര, എത്ര കാലമായി തരാനുണ്ട്, നിങ്ങൾ ആർക്ക് കൊടുക്കാനുണ്ട് എന്ന് എപ്പോഴും അറിയാം.",
  "app.ab.1": "ഡാഷ്‌ബോർഡ്: ഇന്നത്തെയും ഈ മാസത്തെയും വിൽപ്പന, കിട്ടാനും കൊടുക്കാനുമുള്ളത്, കൈയിലെ ക്യാഷ്, ബാങ്കിലെ പണം.",
  "app.ab.2": "വന്ന പണം, പോയ പണം: പേയ്മെന്റ് ഒരിക്കൽ എഴുതി അത് തീർക്കുന്ന ബില്ലുകൾ ടിക്ക് ചെയ്യൂ. ഭാഗിക പേയ്മെന്റുകളും അഡ്വാൻസുകളും തനിയെ കൈകാര്യം ചെയ്യും, കസ്റ്റമർ പിടിച്ച TDS ഉം കണക്കിൽ വരും.",
  "app.ab.3": "കുടിശ്ശികയും പഴക്കവും: ആര് എത്ര തരാനുണ്ട്, 0–30, 31–60, 61–90, 90 ദിവസത്തിൽ കൂടുതൽ എന്ന് തിരിച്ച്, തയ്യാറായ WhatsApp ഓർമ്മപ്പെടുത്തലോടെ.",
  "app.ab.4": "പാർട്ടി സ്റ്റേറ്റ്‌മെന്റ്: ഏത് തീയതികൾക്കുമുള്ള സ്റ്റേറ്റ്‌മെന്റ് ഓഫ് അക്കൗണ്ട്, പ്രിന്റ് ചെയ്യാനോ PDF ആയി അയയ്ക്കാനോ.",
  "app.ab.5": "വാങ്ങലും ചെലവുകളും: സപ്ലയർ ബില്ലുകൾ, CGST, SGST അല്ലെങ്കിൽ IGST തനിയെ; വാങ്ങിയത് തിരികെ; വാടക, കറന്റ്, ഇന്ധനം പോലുള്ള ദിവസച്ചെലവുകൾ.",
  "app.ab.6": "ക്യാഷ് ബുക്കും ബാങ്ക് ബുക്കും: ഓരോ ക്യാഷ്, ബാങ്ക് എൻട്രിയും, നടപ്പ് ബാലൻസോടെ.",
  "app.ab.7": "ഒറ്റ ക്ലിക്കിൽ മാറ്റം: ക്വട്ടേഷനിൽ നിന്ന് സെയിൽസ് ഓർഡർ, ഡെലിവറി ചലാൻ അല്ലെങ്കിൽ ഇൻവോയ്സ്, വീണ്ടും ടൈപ്പ് ചെയ്യാതെ.",
  "app.ab.end": "ഉള്ളിൽ, ഓരോ ബില്ലും പേയ്മെന്റും ചെലവും അക്കൗണ്ടന്റ് പ്രതീക്ഷിക്കുന്ന ശരിയായ ഡബിൾ-എൻട്രി കണക്കായി മാറുന്നു.",
  "app.ab.link": "ആപ്പ് എങ്ങനെ പ്രവർത്തിക്കുന്നു എന്ന് വായിക്കൂ",
