  "g1.w.nopos": "ബിൽ {no}: വിതരണ സ്ഥലമോ വാങ്ങുന്നയാളുടെ സംസ്ഥാനമോ ഇല്ല, അതുകൊണ്ട് നിങ്ങളുടെ സ്വന്തം സംസ്ഥാനം എടുത്തു.",
  "g1.w.noorig": "നോട്ട് {no}: യഥാർത്ഥ ഇൻവോയ്സ് {o} ഇവിടെ സേവ് ചെയ്തിട്ടില്ല, അതുകൊണ്ട് വിതരണ സ്ഥലവും ടേബിളും നോട്ടിൽ നിന്നുതന്നെ എടുത്തു.",
  "g1.w.adv": "അഡ്വാൻസ് {no} ടേബിൾ 11A-യിലാണ്. ഇൻവോയ്സ് ഉണ്ടാക്കുമ്പോൾ പോർട്ടലിൽ ടേബിൾ 11B-യിൽ ക്രമീകരണം കാണിക്കുക.",
  "g1.w.plain": "GST ഇല്ലാത്ത {n} ബില്ലുകൾ (സാധാരണ ഇൻവോയ്സുകൾ അല്ലെങ്കിൽ GST ഇല്ലാത്ത നോട്ടുകൾ) ഒഴിവാക്കി.",
  "g1.w.dup": "“{s}” നമ്പർ സീരീസിൽ ഒരേ നമ്പർ രണ്ടുതവണ ഉണ്ട്. ഫയൽ ചെയ്യുന്നതിന് മുൻപ് തിരുത്തുക.",
  "g1.w.irn": "ബിൽ {no}-ന് ഇ-ഇൻവോയ്സ് IRN ഉണ്ട്: പോർട്ടൽ അത് GSTR-1-ൽ ഇതിനകം ചേർക്കും, അതുകൊണ്ട് അവിടെ പരിശോധിക്കുക, രണ്ടുതവണ അപ്‌ലോഡ് ചെയ്യരുത്.",
  "g1.w.gap": "“{s}” നമ്പർ സീരീസിൽ {n} നമ്പർ(കൾ) വിട്ടുപോയി. അവ ടേബിൾ 13-ൽ റദ്ദാക്കിയവയായി കണക്കാക്കും; മറ്റൊരു മാസത്തിൽ നൽകിയതാണെങ്കിൽ മാറ്റുക.",
