  "bk.choose": "നിങ്ങളുടെ Excel അല്ലെങ്കിൽ CSV ഫയൽ തിരഞ്ഞെടുക്കുക",
  "bk.h.s2": "ഒരു ഐറ്റത്തിന് ഒരു വരി. ഒരേ ഇൻവോയ്സ് നമ്പറുള്ള വരികൾ ചേർന്ന് ഒരു ഇൻവോയ്സ് ആകും. നിങ്ങളുടെ സ്വന്തം ഷീറ്റിലെ തലക്കെട്ടുകൾ ഞങ്ങളുടേതിന് സമാനമാണെങ്കിൽ അതും പ്രവർത്തിക്കും.",
  "bk.h.s2e": "ഒരു ഐറ്റത്തിന് ഒരു വരി. ഒരേ ഡോക്യുമെന്റ് നമ്പറുള്ള വരികൾ ചേർന്ന് ഒരു ഇ-വേ ബിൽ ആകും. വാഹനം ഒഴിച്ചിട്ടാൽ Part A മാത്രം ഉണ്ടാകും; വാഹനം പിന്നീട് ചേർക്കാം.",
  "bk.reading": "ഫയൽ വായിക്കുന്നു…",
