  "bk.fixfirst": "നിങ്ങളുടെ ഷീറ്റിലെ പ്രശ്നങ്ങൾ ശരിയാക്കി, സേവ് ചെയ്ത്, വീണ്ടും തിരഞ്ഞെടുക്കുക.",
  "bk.made": "{file} നിങ്ങളുടെ ഡൗൺലോഡ്സിൽ സേവ് ആയി (ഇൻവോയ്സുകൾ: {n}). ഇത് ഇ-ഇൻവോയ്സ് പോർട്ടലിൽ അപ്‌ലോഡ് ചെയ്യുക.",
  "bk.madeewb": "{file} നിങ്ങളുടെ ഡൗൺലോഡ്സിൽ സേവ് ആയി (ഇ-വേ ബില്ലുകൾ: {n}). ഇത് ഇ-വേ ബിൽ പോർട്ടലിൽ അപ്‌ലോഡ് ചെയ്യുക.",
