  "bk.state": "വരി {r}: “{v}” ഞങ്ങൾക്ക് അറിയാവുന്ന സംസ്ഥാന കോഡ് അല്ല (03 അല്ലെങ്കിൽ 27 പോലെ 2 അക്കം ടൈപ്പ് ചെയ്യുക).",
  "bk.twodates": "വരി {r}: ഈ വരിയുടെ തീയതി, അതേ ഡോക്യുമെന്റിന്റെ ആദ്യ വരിയുടെ തീയതിയിൽ നിന്ന് വ്യത്യസ്തമാണ്.",
  "bk.sup": "വരി {r}: സപ്ലൈ തരം “{v}” B2B, SEZWP, SEZWOP, EXPWP, EXPWOP, DEXP എന്നിവയിൽ ഒന്നല്ല.",
  "bk.sub": "വരി {r}: “{v}” പോർട്ടലിന് അറിയാവുന്ന സബ് സപ്ലൈ തരം അല്ല.",
  "bk.dtype": "വരി {r}: ഈ സബ് സപ്ലൈ തരത്തിനൊപ്പം ഡോക്യുമെന്റ് തരം {v} അനുവദിക്കില്ല (അനുവദിച്ചത്: {ok}).",
  "bk.subdesc": "വരി {r}: സബ് സപ്ലൈ തരം “Others” ആണെങ്കിൽ, അത് എന്താണെന്ന് “Sub Supply Description”-ൽ എഴുതുക.",
  "bk.mode": "വരി {r}: ട്രാൻസ്പോർട്ട് രീതി “{v}” Road, Rail, Air അല്ലെങ്കിൽ Ship ആയിരിക്കണം.",
  "bk.road": "വരി {r}: റോഡ് മാർഗമാണെങ്കിൽ വാഹന നമ്പറോ ട്രാൻസ്പോർട്ടർ ID-യോ നൽകുക.",
  "bk.raildoc": "വരി {r}: റെയിൽ അല്ലെങ്കിൽ വിമാന മാർഗമാണെങ്കിൽ ട്രാൻസ്പോർട്ട് ഡോക്യുമെന്റ് നമ്പറും തീയതിയും നൽകുക.",
  "bk.zero": "ഡോക്യുമെന്റ് തരം {v} ആണെങ്കിൽ ഓരോ ഐറ്റത്തിനും GST 0% വേണം.",
  "bk.s3": "പോർട്ടലിന്റെ മറുപടി ലോഡ് ചെയ്യുക",
  "bk.h.s3": "അപ്‌ലോഡിന് ശേഷം, പോർട്ടലിൽ നിന്ന് റിസൽട്ട് (JSON അല്ലെങ്കിൽ Excel) ഡൗൺലോഡ് ചെയ്ത് ഇവിടെ തിരഞ്ഞെടുക്കുക. IRN, Ack നമ്പർ, ഒപ്പിട്ട QR കോഡ് എന്നിവ ഓരോ സേവ് ചെയ്ത ഇൻവോയ്സിലും ചേരും, പ്രിന്റിന് തയ്യാറായി.",
  "bk.h.s3e": "ജനറേറ്റ് ചെയ്ത ശേഷം, പോർട്ടലിൽ നിന്ന് റിസൽട്ട് ഡൗൺലോഡ് ചെയ്ത് ഇവിടെ തിരഞ്ഞെടുക്കുക. ഇ-വേ ബിൽ നമ്പറുകൾ സേവ് ചെയ്ത ഇൻവോയ്സുകളിലും താഴെയുള്ള വാഹന ഫയലിലും ചേരും.",
  "bk.got": "മറുപടിയിൽ കണ്ടത്: {n}. സേവ് ചെയ്ത ഇൻവോയ്സുകളുമായി പൊരുത്തപ്പെട്ടത്: {k}.",
  "bk.open": "തുറന്ന് പ്രിന്റ് ചെയ്യുക",
  "bk.notsaved": "ഇവിടെ സേവ് ആയിട്ടില്ല",
  "bk.h.notsaved": "ചില നമ്പറുകൾ സേവ് ചെയ്ത ഇൻവോയ്സുമായി പൊരുത്തപ്പെട്ടില്ല. ആദ്യം ഇൻവോയ്സുകൾ സേവ് ചെയ്യുക (മുകളിൽ ടിക് ചെയ്യുക, അല്ലെങ്കിൽ ബില്ലിംഗ് മേക്കറിൽ ഉണ്ടാക്കുക), എന്നിട്ട് മറുപടി വീണ്ടും ലോഡ് ചെയ്യുക.",
  "bk.pb": "വാഹനം പിന്നീട് ചേർക്കുക (Part B)",
  "bk.h.pb": "വാഹനമില്ലാതെ ഉണ്ടാക്കിയ ഇ-വേ ബില്ലുകൾക്ക്, അല്ലെങ്കിൽ സാധനം മറ്റൊരു വാഹനത്തിലേക്ക് മാറ്റുമ്പോൾ. പോർട്ടലിന്റെ വാഹന അപ്‌ഡേറ്റ് ഫയൽ ഉണ്ടാക്കും. Part A മാത്രമുള്ള ഇ-വേ ബില്ലിന്, വാലിഡിറ്റി ഈ അപ്‌ഡേറ്റ് മുതൽ തുടങ്ങും.",
  "bk.pbplace": "വാഹനം പുറപ്പെടുന്ന സ്ഥലം",
  "bk.pbreason": "കാരണം",
  "bk.pbremark": "റിമാർക്ക് (Others-ന് വേണം)",
