  "g3.b.i3": "(3) റിവേഴ്സ് ചാർജിലുള്ള ഉള്ളിലേക്കുള്ള വിതരണങ്ങൾ",
  "g3.b.i4": "(4) ISD യിൽ നിന്ന്",
