  "b1.ageh": "ഡ്യൂ ഡേറ്റ് ഉള്ള ബില്ലുകൾ (അല്ലെങ്കിൽ പാർട്ടിയുടെ ക്രെഡിറ്റ് ദിവസം) ഡ്യൂ ഡേറ്റ് മുതൽ എണ്ണുന്നു, അതിനാൽ ഇനിയും ഡ്യൂ ആകാത്ത ബിൽ 0-30 ദിവസത്തിൽ നിൽക്കും. ബാക്കി ബിൽ തീയതി മുതൽ.",
  "b1.charges": "അധിക ചാർജ്",
  "b1.addchg": "ചാർജ് ചേർക്കുക (വണ്ടിക്കൂലി, പാക്കിംഗ്…)",
  "b1.chgname": "ചാർജ്",
  "b1.chgamt": "തുക (₹)",
  "b1.chgmain": "പ്രധാന ഐറ്റം പോലെ",
  "b1.chgh": "ബില്ലിൽ ഈടാക്കുന്ന വണ്ടിക്കൂലി, പാക്കിംഗ് അല്ലെങ്കിൽ ഇൻഷുറൻസ് ടാക്സബിൾ വാല്യുവിന്റെ ഭാഗമാണ് (CGST ആക്ട് സെക്ഷൻ 15(2)(c)). \"പ്രധാന ഐറ്റം പോലെ\" യിൽ ഏറ്റവും കൂടിയ തുകയുള്ള ഐറ്റത്തിന്റെ GST റേറ്റ് വരും.",
  "b1.tcs": "TCS (ഉറവിടത്തിൽ നികുതി പിരിവ്)",
  "b1.tcson": "ഈ ബില്ലിൽ TCS ഈടാക്കുക",
  "b1.tcsh": "വിൽക്കുന്നയാൾ ആദായനികുതി പിരിക്കേണ്ട വിൽപ്പനകൾക്ക് മാത്രം: ആദായനികുതി നിയമം 2025 സെക്ഷൻ 394 (മുമ്പ് സെക്ഷൻ 206C). ഫിനാൻസ് ആക്ട് 2026-ന് ശേഷമുള്ള റേറ്റ്: മദ്യം, തെണ്ടു ഇല, തടി അല്ലെങ്കിൽ വനവിഭവം, സ്ക്രാപ്പ്, കൽക്കരി, ലിഗ്നൈറ്റ് അല്ലെങ്കിൽ ഇരുമ്പയിര് 2%; ₹10 ലക്ഷത്തിന് മുകളിലുള്ള വാഹനം അല്ലെങ്കിൽ നോട്ടിഫൈ ചെയ്ത സാധനം 1%; വിദേശ ടൂർ പാക്കേജ് 2%; പാർക്കിംഗ്, ടോൾ പ്ലാസ, ഖനി 2%. 1 മുതൽ 5 വരെ സാധനങ്ങൾക്ക്, ഇത് നിർമ്മാണത്തിനാണ്, കച്ചവടത്തിനല്ല എന്ന് വാങ്ങുന്നയാൾ എഴുതി നൽകിയാൽ TCS ഇല്ല. മറ്റ് സാധനങ്ങൾക്ക് TCS ഇല്ല (₹50 ലക്ഷത്തിന്റെ പഴയ നിയമം ഇല്ല).",
  "b1.tcssec": "സെക്ഷനും എന്തിനും",
  "b1.tcsrate": "TCS റേറ്റ് (%)",
  "b1.tcsrh": "മുകളിൽ എന്തിനെന്ന് തിരഞ്ഞെടുത്താൽ റേറ്റ് നിയമത്തിൽ നിന്ന് നിറയും; മാറ്റാം.",
  "b1.tcsbase": "TCS എന്തിന്മേൽ",
  "b1.tcs_tot": "GST ഉൾപ്പെടെ ബിൽ തുക",
  "b1.tcs_tax": "ടാക്സബിൾ വാല്യു (GST ഇല്ലാതെ)",
  "b1.sumtcs": "TCS {v}",
  "b1.v_chg": "അധിക ചാർജിന് പേര് കൊടുക്കുക, ഉദാ. വണ്ടിക്കൂലി.",
  "b1.v_tcs": "TCS റേറ്റ് എഴുതുക, അല്ലെങ്കിൽ TCS ടിക്ക് മാറ്റുക.",
  "b1.v_tcs10": "വാഹനത്തിനോ നോട്ടിഫൈഡ് സാധനങ്ങൾക്കോ TCS, ഒരു ഐറ്റത്തിന്റെ വില ₹10 ലക്ഷത്തിന് മുകളിലാണെങ്കിൽ മാത്രം (നോട്ടിഫിക്കേഷൻ 36/2025 സംബന്ധിച്ച CBDT FAQ, 23 ഏപ്രിൽ 2025). ഈ ബില്ലിൽ അങ്ങനെയൊരു ഐറ്റം ഇല്ല. TCS ടിക്ക് മാറ്റുക.",
  "b1.c_tcs10g": "GST ഇല്ലാതെ ഒരു ഐറ്റവും ₹10 ലക്ഷം കടന്നിട്ടില്ല, GST ചേർത്താൽ മാത്രം കടക്കുന്നു. ആക്ടിൽ \"വാല്യു\" എന്നാണ്; ഈ ലിമിറ്റിൽ GST കൂട്ടണോ എന്ന് ഒരു സർക്കുലറും തീരുമാനിച്ചിട്ടില്ല. ഈ ബില്ലിൽ TCS പിരിക്കണോ?",
  "b1.tcsbh": "CBDT സർക്കുലർ 17/2020 (പാരാ 4.6.1, പഴയ സെക്ഷൻ 206C ക്ക്): TCS കിട്ടിയ തുകയിൽ GST ഉൾപ്പെടെ പിരിക്കും; GST, ഡിസ്കൗണ്ട്, റിട്ടേൺ എന്നിവയ്ക്കായി ഒന്നും കുറയ്ക്കില്ല. ടാക്സബിൾ വാല്യു നിങ്ങളുടെ CA പറഞ്ഞാൽ മാത്രം തിരഞ്ഞെടുക്കുക.",
  "b1.cntcs": "ബിൽ {no} ൽ {v} TCS ഉണ്ടായിരുന്നു. ഈ ക്രെഡിറ്റ് നോട്ട് ആ TCS കുറയ്ക്കുന്നില്ല: CBDT സർക്കുലർ 17/2020 (പാരാ 4.6.1) പ്രകാരം സെയിൽസ് റിട്ടേണിന് അഡ്ജസ്റ്റ്മെന്റ് ഇല്ല. വാങ്ങുന്നയാൾ ഈ TCS തന്റെ ഇൻകം ടാക്സ് റിട്ടേണിൽ ക്ലെയിം ചെയ്യും.",
  "b1.tcspan": "വാങ്ങുന്നയാളുടെ PAN",
  "b1.tcspanh": "വാങ്ങുന്നയാളുടെ GSTIN-ൽ നിന്ന് സ്വയം എടുക്കും. ശരിയായ PAN ഇല്ലെങ്കിൽ TCS കൂടിയ റേറ്റിൽ വരും (സെക്ഷൻ 397(2)), നിർമ്മാണ ഡിക്ലറേഷൻ സാധുവല്ല.",
  "b1.tcsnr": "വാങ്ങുന്നയാൾ പ്രവാസിയാണ്, ഇന്ത്യയിൽ ബിസിനസ് സ്ഥലം ഇല്ല (PAN ഇല്ലാത്ത കൂടിയ റേറ്റ് ബാധകമല്ല)",
  "b1.tcsnopan": "വാങ്ങുന്നയാൾക്ക് ശരിയായ PAN ഇല്ല: TCS {r}% (റേറ്റിന്റെ ഇരട്ടി അല്ലെങ്കിൽ 5%, ഏതാണോ കൂടുതൽ, 20% വരെ, സെക്ഷൻ 397(2)).",
  "b1.repeat": "ഈ ബിൽ വീണ്ടും ഇടുക",
