  "b1.rep_m": "എല്ലാ മാസവും",
  "b1.rep_q": "എല്ലാ ക്വാർട്ടറിലും",
  "b1.reph": "സ്വയം ഒന്നും ഉണ്ടാകില്ല: Nivesh Sahayak ആപ്പിൽ ഉണ്ടാക്കേണ്ട കോപ്പികളുടെ ലിസ്റ്റ് വരും, നിങ്ങൾ ടാപ്പ് ചെയ്ത് ഉണ്ടാക്കും.",
  "b1.repuntil": "എന്ന് വരെ",
  "b1.repuh": "എപ്പോഴും തുടരാൻ ഒഴിച്ചിടുക.",
  "b1.rep_t": "ആവർത്തിക്കുന്ന ബില്ലുകൾ",
  "b1.rep_p": "\"ഈ ബിൽ വീണ്ടും ഇടുക\" ഉപയോഗിച്ച് സേവ് ചെയ്ത ബില്ലുകൾ. വേണ്ട കോപ്പികൾ ടിക്ക് ചെയ്ത് ബട്ടൺ അമർത്തുക; ഓരോ കോപ്പിക്കും അടുത്ത ഇൻവോയ്സ് നമ്പറും കാണിച്ച തീയതിയും കിട്ടും. നിങ്ങളുടെ ടാപ്പ് ഇല്ലാതെ ഒന്നും ഉണ്ടാകില്ല.",
  "b1.rep_due": "ഉണ്ടാക്കാനുള്ളവ",
