  "b1.rep_all": "എല്ലാ ആവർത്തിക്കുന്ന ബില്ലുകളും",
  "b1.rep_from": "{d} ലെ {no} ൽ നിന്ന് · {n} കോപ്പികൾ ഉണ്ടാക്കി",
  "b1.rep_how": "ബിൽ ആവർത്തിക്കാൻ അത് ഇൻവോയ്സ് മേക്കറിൽ തുറന്ന് \"ഈ ബിൽ വീണ്ടും ഇടുക\" യിൽ \"എല്ലാ മാസവും\" അല്ലെങ്കിൽ \"എല്ലാ ക്വാർട്ടറിലും\" തിരഞ്ഞെടുക്കുക.",
