  "b1.bin": "റീസൈക്കിൾ ബിൻ",
  "b1.binp": "ഡിലീറ്റ് ചെയ്ത ബിസിനസ്, പാർട്ടി, ഐറ്റം, ഡോക്യുമെന്റ് ഇവിടെ {n} ദിവസം ഉണ്ടാകും, പിന്നെ സ്ഥിരമായി പോകും. റീസ്റ്റോർ ചെയ്താൽ പഴയതുപോലെ തിരികെ വരും.",
