  "b1.binned": "റീസൈക്കിൾ ബിനിലേക്ക് മാറ്റി. 30 ദിവസം വരെ റീസ്റ്റോർ ചെയ്യാം.",
  "b1.hist": "മാറ്റങ്ങളുടെ രേഖ",
