  "b1.nolog": "ഇതുവരെ മാറ്റമൊന്നും രേഖപ്പെടുത്തിയിട്ടില്ല.",
  "b1.thisdev": "ഈ ഡിവൈസ്",
  "b1.logp": "ഏത് Nivesh Sahayak സൈറ്റിലും ബിസിനസ്, പാർട്ടി, ഐറ്റം അല്ലെങ്കിൽ ഡോക്യുമെന്റ് ചേർക്കുകയോ മാറ്റുകയോ ഡിലീറ്റ് ചെയ്യുകയോ റീസ്റ്റോർ ചെയ്യുകയോ ചെയ്താൽ തീയതി, സമയം, പേര്, എന്ത് മാറി എന്നിവ ഇവിടെ രേഖപ്പെടുത്തും. ഈ രേഖകൾ മാറ്റാനോ നീക്കാനോ കഴിയില്ല.",
  "b1.logrule": "1 ഏപ്രിൽ 2023 മുതൽ കമ്പനികൾ ഇത്തരം ഓഡിറ്റ് ട്രെയിൽ സൂക്ഷിക്കുന്ന അക്കൗണ്ട്സ് സോഫ്റ്റ്‌വെയർ ഉപയോഗിക്കണം (കമ്പനീസ് (അക്കൗണ്ട്സ്) റൂൾസ് 2014, റൂൾ 3(1)). ഇത് ഈ ബ്രൗസറിലും നിങ്ങളുടെ ബാക്കപ്പ് ഫയലിലും ഉണ്ടാകും.",
  "b1.logmore": "{n} ൽ പുതിയ 300 കാണിക്കുന്നു. എല്ലാത്തിനും Excel ഫയൽ ഡൗൺലോഡ് ചെയ്യുക.",
