  "b2.jvh": "ഒരു ബില്ലും പേയ്മെന്റും ചേരാത്തപ്പോൾ ജേണൽ എൻട്രി തുക ഒരു അക്കൗണ്ടിൽ നിന്ന് മറ്റൊന്നിലേക്ക് മാറ്റുന്നു: കൊടുത്തതോ കിട്ടിയതോ ആയ ഡിസ്കൗണ്ട്, ചുമത്തിയ പലിശ, കിട്ടാക്കടം (ബാഡ് ഡെറ്റ്), കൊണ്ടുവന്ന മൂലധനം, സ്വന്തം ആവശ്യത്തിന് എടുത്ത പണം, ലോൺ, അല്ലെങ്കിൽ ഒരു തിരുത്ത്. ഡെബിറ്റും ക്രെഡിറ്റും തുല്യമായിരിക്കണം.",
  "b2.jvhelp": "ഓരോ വരിയിലും ഒരു അക്കൗണ്ടും ഡെബിറ്റ് (Dr) അല്ലെങ്കിൽ ക്രെഡിറ്റ് (Cr) തുകയും ഉണ്ട്. പാർട്ടി വരി കസ്റ്റമർ തരാനുള്ളതോ സപ്ലയർക്ക് കൊടുക്കാനുള്ളതോ മാറ്റുന്നു, അത് അവരുടെ സ്റ്റേറ്റ്മെന്റിലും കുടിശ്ശികയിലും കാണും. ചെലവും മറ്റ് വരുമാനവും പ്രോഫിറ്റ് ആൻഡ് ലോസിലേക്ക്; മൂലധനം, ഡ്രോയിംഗ്സ്, ലോൺ, ഫിക്സഡ് അസറ്റ് ബാലൻസ് ഷീറ്റിലേക്ക്.",
