  "b2.fah": "നിങ്ങളുടെ ബിസിനസ് വർഷങ്ങളോളം ഉപയോഗിക്കുന്ന മെഷീനുകൾ, കമ്പ്യൂട്ടറുകൾ, ഫർണിച്ചർ, വാഹനങ്ങൾ, കെട്ടിടങ്ങൾ. രജിസ്റ്റർ ഓരോ വർഷത്തെയും തേയ്മാനം കണക്കാക്കുന്നു; ഒറ്റ ടാപ്പിൽ അത് അക്കൗണ്ടിൽ ചേർക്കാം.",
