  "b2.addhalf": "ചേർത്തത് (180 ദിവസത്തിൽ കുറവ്)",
  "b2.sales": "വിറ്റ തുക",
  "b2.dep": "തേയ്മാനം",
  "b2.closewdv": "ക്ലോസിംഗ് WDV",
  "b2.gain": "ലാഭം {a}: അക്കൗണ്ടന്റിനോട് ചോദിക്കുക",
  "b2.farules": "തേയ്മാനം എങ്ങനെ കണക്കാക്കുന്നു",
  "b2.farule1": "അക്കൗണ്ടിലെ തേയ്മാനം കമ്പനീസ് ആക്ട്, 2013 ഷെഡ്യൂൾ II അനുസരിച്ചാണ്: ഓരോ തരം അസറ്റിനും ഒരു ഉപയോഗ കാലമുണ്ട് (ഉദാ. കമ്പ്യൂട്ടർ 3 വർഷം, ഫർണിച്ചർ 10 വർഷം, പ്ലാന്റ് ആൻഡ് മെഷിനറി 15 വർഷം, കാർ 8 വർഷം), ബാക്കി മൂല്യം സാധാരണ വിലയുടെ 5% ൽ കൂടില്ല, വർഷത്തിനിടയിൽ ചേർത്തതോ വിറ്റതോ ആയ അസറ്റിന് ഉപയോഗിച്ച ദിവസങ്ങൾക്ക് മാത്രം തേയ്മാനം. സ്ട്രെയിറ്റ് ലൈൻ (SLM: എല്ലാ വർഷവും ഒരേ തുക) അല്ലെങ്കിൽ റിട്ടൺ ഡൗൺ വാല്യു (WDV: ബാക്കി തുകയിൽ നിശ്ചിത റേറ്റ്) തിരഞ്ഞെടുക്കുക. പ്രൊപ്രൈറ്റർമാരും ഫേമുകളും മിക്കപ്പോഴും ഇതേ രീതി പിന്തുടരുന്നു; തീരുമാനം നിങ്ങളുടെ അക്കൗണ്ടന്റിന്റേതാണ്.",
  "b2.farule2": "ഇൻകം ടാക്സ് തേയ്മാനം ഓരോ ബ്ലോക്കിനും വെവ്വേറെ കണക്കാക്കുന്നു: ബ്ലോക്ക് റേറ്റിൽ റിട്ടൺ ഡൗൺ വാല്യു (ഉദാ. പ്ലാന്റ് ആൻഡ് മെഷിനറി 15%, ഫർണിച്ചർ 10%, കമ്പ്യൂട്ടർ 40%), വർഷത്തിൽ 180 ദിവസത്തിൽ കുറവ് ഉപയോഗിച്ച അസറ്റിന് പകുതി റേറ്റ്, വിൽപനയുടെ പണം ബ്ലോക്കിൽ നിന്ന് കുറയും. ഇത് ഇൻകം ടാക്സ് റിട്ടേണിന് മാത്രം, അക്കൗണ്ടിൽ ഒരിക്കലും ചേർക്കില്ല. നൽകിയിരിക്കുന്ന റേറ്റുകൾ സാധാരണ ബ്ലോക്ക് റേറ്റുകളാണ്: നിങ്ങളുടെ അക്കൗണ്ടന്റുമായി ഉറപ്പാക്കുക, പ്രത്യേകിച്ച് 1 ഏപ്രിൽ 2026 മുതൽ ഇൻകം-ടാക്സ് ആക്ട്, 2025 പ്രകാരമുള്ള വർഷങ്ങൾക്ക്.",
  "b2.farule3": "നിങ്ങൾ 'തേയ്മാനം ചേർക്കുക' അമർത്തുമ്പോൾ മാത്രമേ തേയ്മാനം അക്കൗണ്ടിൽ പോകൂ: വർഷത്തിലെ അവസാന ദിവസത്തെ (അല്ലെങ്കിൽ വർഷത്തിനിടയിൽ ഇന്നത്തെ) ജേണൽ എൻട്രി തേയ്മാനത്തെ ഡെബിറ്റ് ചെയ്ത് ഓരോ അസറ്റും കുറയ്ക്കുന്നു. പിന്നീട് അസറ്റ് മാറ്റിയാൽ വീണ്ടും ചേർക്കുക, വ്യത്യാസം മാത്രം ചേരും.",
